 private void AnatemaSkill101(int n){if(battle==null)return;var st=game.State;int cost=n==1?8:n==2?10:18;if(st.Mind<cost){battle.Log="Mente insufficiente.";return;}st.Mind-=cost;if(n==1){battle.Guard=true;battle.Log="Volontà ferrea. Ti prepari a resistere.";}else{string part=n==2?"torace":"testa";int damage=CombatStats100.SkillDamage(n==2?24:29,CombatStats100.Effective(game).Attack,6);battle.Parts[part]=Math.Max(0,battle.Parts[part]-damage);battle.Log=$"{game.GetSkills()[n]}: {damage} danni fisici.";if(battle.Parts[part]==0){WinBattle();return;}}RequestEnemy95();}
 private void DrawAnatemaCombat101(){string key=InjuryKey();string mask=key.Substring(key.Length-2);int pose=heroAttack75>0?(HeroProgress95<.35f?1:HeroProgress95<.72f?2:1):enemyAttack75>0?(enemyGuard95?1:4):0;var tex=Art(pose==0?"rig95_"+key+"_full":"anatema101_"+mask+"_"+pose);if(tex==null)return;float h=288,w=h*tex.GetWidth()/tex.GetHeight();DrawEllipse(333,459,45,10,new Color(.015f,.01f,.01f,.54f));DrawTextureRect(tex,new Rect2(333-w/2,457-h,w,h),false);}
 private void CheckAnatema101(){int n=0;void C(bool ok,string why){if(!ok)throw new Exception(why);n++;}RebellionPath101="user://test_rebellion101.profile";string f=ProjectSettings.GlobalizePath(RebellionPath101);System.IO.File.Delete(f);C(HeroCount101==3,"hidden");screen=Screen.Title;_UnhandledKeyInput(new InputEventKey{Keycode=Key.F2,Pressed=true});C(HeroCount101==4&&hero==HeroId.Anatema&&screen==Screen.Hero,"F2");C(RebellionMask101()==0,"debug not permanent");BeginNew60();C(screen==Screen.Origin&&game.State.Hero==HeroId.Anatema,"start fourth");C(CombatStats100.Base(hero).ArcaneAttack==0,"stats");C(GameRules.FromJson(game.ToJson()).State.Hero==hero,"save roundtrip");C(Art("portrait_anatema")!=null,"portrait");for(int i=0;i<16;i++){string k="anatema_"+i.ToString("D2");C(Art("anim_"+k)!=null,"atlas");C(Art("rig95_"+k+"_full")!=null,"battle");for(int j=1;j<5;j++)C(Art("anatema101_"+i.ToString("D2")+"_"+j)!=null,"pose");}debugAnatema101=false;foreach(var h in new[]{HeroId.Gladia,HeroId.Ambrosh,HeroId.Roderick}){game.StartNew(h,Difficulty.Sopravvivenza);OriginChoices67.Apply(game,0,1);OriginChoices67.Apply(game,1,h==HeroId.Roderick?2:h==HeroId.Gladia?0:1);OriginChoices67.Apply(game,2,1);RecordRebellion101();C((RebellionMask101()&(1<<(int)h))!=0,"rebellion stored");}C(HeroCount101==4,"natural unlock");System.IO.File.Delete(f);GD.Print($"ANATEMA101_OK {n}");GetTree().Quit();}
